  {
    role: "user",
    content: "I have a shellfish allergy and I cook a lot of Thai green curry.",
  },
  {
    role: "assistant",
    content: "Got it. Logged your shellfish allergy and Thai green curry preference.",
  },
  {
    role: "user",
    content: "I always use jasmine rice as the side.",
